// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 seedBalance, uint256 minSum, uint256 amount) public {
        // Bound to a wide but sensible admissible domain.
        seedBalance = bound(seedBalance, 1, 1e30);
        minSum = bound(minSum, 0, seedBalance);
        amount = bound(amount, 0, seedBalance - minSum);

        address actor = address(0xBEEF);
        vm.deal(actor, seedBalance);

        // Set up the LogFile so external calls do not revert.
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(minSum);
        c.Initialized();

        vm.prank(actor);
        c.Deposit{value: seedBalance}();

        uint256 beforeBal = c.balances(actor);

        bool ok;
        vm.prank(actor);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterBal = c.balances(actor);

        // Reference: successful Collect never increases the caller's balance.
        // Mutant: successful Collect adds _am, so afterBal > beforeBal.
        assertTrue(!ok || afterBal <= beforeBal);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
